                    unsafe GenericGatherByLane<UInt32>.gather(
                        from: source.baseAddress!,
                        indices: indices,
                        where: mask,
                        otherwise: otherwise
                    ),
                    unsafe H.gather(
                        from: source.baseAddress!,
                        indices: indices,
                        where: mask,
                        otherwise: otherwise
                    )
                )
            }
            mismatches.check(
                portResult,
                referenceResult,
                "otherwise: \(describe(otherwise)), mask: \(describe(mask)), from: \(describe(from)), indices: \(describe(indices))"
            )
        }
        mismatches.record()
    }

